private boolean mIsTvRequired = false;
private Location mTvFeatureLocation;
private boolean mHasLeanbackLauncher = false;

@Override public void beforeCheckEachProject(@NonNull Context context) { mIsTvRequired=false; mTvFeatureLocation=null; mHasLeanbackLauncher=false; }

@Override public Collection<String> getApplicableElements() { return Arrays.asList(TAG_USES_FEATURE, TAG_ACTIVITY); }

@Override public void visitElement(XmlContext context, Element element) {
  if (TAG_USES_FEATURE.equals(element.getTagName())) {
    String name = element.getAttributeNS(ANDROID_URI, ATTR_NAME);
    if (name != null && (name.contains("leanback") || name.contains("television"))) {
      String required = element.getAttributeNS(ANDROID_URI, ATTR_REQUIRED);
      if (required == null || required.isEmpty() || Boolean.parseBoolean(required)) {
        mIsTvRequired = true;
        if (mTvFeatureLocation == null) {
          mTvFeatureLocation = context.getElementLocation(element);
        }
      }
    }
  } else if (TAG_ACTIVITY.equals(element.getTagName())) {
    if (hasLeanbackLauncher(element)) {
      mHasLeanbackLauncher = true;
    }
  }
}

private boolean hasLeanbackLauncher(Element activity) {
  NodeList filters = activity.getElementsByTagName(TAG_INTENT_FILTER);
  for (int i=0; i<filters.getLength(); i++) {
    Element filter = (Element) filters.item(i);
    boolean hasMain = false;
    boolean hasLeanback = false;
    NodeList children = filter.getChildNodes();
    for (int j=0; j<children.getLength(); j++) {
      Node child = children.item(j);
      if (child.getNodeType() == Node.ELEMENT_NODE) {
        Element e = (Element) child;
        String tag = e.getTagName();
        if (TAG_ACTION.equals(tag)) {
          String name = e.getAttributeNS(ANDROID_URI, ATTR_NAME);
          if (ACTION_MAIN.equals(name)) hasMain = true;
        } else if (TAG_CATEGORY.equals(tag)) {
          String name = e.getAttributeNS(ANDROID_URI, ATTR_NAME);
          if (CATEGORY_LEANBACK_LAUNCHER.equals(name)) hasLeanback = true;
        }
      }
    }
    if (hasMain && hasLeanback) return true;
  }
  return false;
}

@Override public void afterCheckEachProject(@NonNull Context context) {
  if (mIsTvRequired && !mHasLeanbackLauncher && mTvFeatureLocation != null) {
    context.report(ISSUE, mTvFeatureLocation, "Missing `LEANBACK_LAUNCHER` intent filter. TV apps must have an activity with action MAIN and category LEANBACK_LAUNCHER.");
  }
}

